function autoVisualFor(d){const ty=d.m?'num':fieldType(d.t,d.c);if(d.m||ty==='num'||ty==='int'){const v=newVisual('card');v.fields.values=[valItem(d)];return v}const v=newVisual(ty==='date'?'line':'col');v.fields.axis=[{t:d.t,c:d.c}];return v}
