function renameQuery(q,n){n=n.trim();if(!n)return;const old=q.name;q.name=n;for(const r of BI.rels){if(r.from.t===old)r.from.t=n;if(r.to.t===old)r.to.t=n}for(const m of BI.measures){if(m.table===old)m.table=n;m.expr=m.expr.split("'"+old+"'[").join("'"+n+"'[")}for(const c of BI.calcCols)if(c.table===old)c.table=n;for(const p of BI.pages)for(const v of p.visuals){for(const k in v.fields)for(const it of v.fields[k]||[])if(it.t===old)it.t=n;for(const f of v.filters||[])if(f.t===old)f.t=n}for(const f of[...BI.rfilters,...BI.pages.flatMap(p=>p.filters)])if(f.t===old)f.t=n;for(const q2 of BI.queries)for(const s of q2.steps)if(s.op==='merge'&&s.with===old)s.with=n;if(BI.layout&&BI.layout[old]){BI.layout[n]=BI.layout[old];delete BI.layout[old]}biChanged()}
function pqFilterDlg(q,T,c,i,step){const vals=[...new Set(T.rows.map(r=>r[i]))].sort(cmpVals).slice(0,500);const L=h('div',{class:'list'});const cbs=vals.map(v=>{const cb=h('input',{type:'checkbox',checked:true});L.append(h('label',{class:'li'},cb,v==null?'(nulo)':cellTxt(v,c)));return[v,cb]});
  const op=sel([['','— lista de valores —'],['eq','é igual a'],['ne','não é igual a'],['gt','maior que'],['ge','maior ou igual'],['lt','menor que'],['le','menor ou igual'],['contains','contém'],['ncontains','não contém'],['starts','começa com'],['empty','é vazio'],['nempty','não é vazio']],'');const a=inp('',{placeholder:c.type==='date'?'dd/mm/aaaa':''});
  dlg('Filtrar '+c.name,h('div',{},h('div',{class:'row2'},op,a),L),[{label:'Cancelar'},{label:'OK',primary:true,act:()=>{if(op.value)step({op:'filter',col:c.name,cmp:op.value,v:a.value});else{const keep=cbs.filter(([v,cb])=>cb.checked).map(([v])=>v==null?'':String(v));if(keep.length<vals.length)step({op:'filter',col:c.name,cmp:'in',vals:keep})}}}])}
function pqGroupDlg(q,T,keys,step){const cols=T.cols.map(c=>c.name);const ks=h('div',{class:'list',style:{maxHeight:'140px'}});const kcb=cols.map(n=>{const cb=h('input',{type:'checkbox',checked:keys.includes(n)||null});ks.append(h('label',{class:'li'},cb,n));return[n,cb]});
  const aggs=h('div',{style:{display:'flex',flexDirection:'column',gap:'6px'}});const addAgg=()=>{const as=inp('Total'),fn=sel([['sum','Soma'],['avg','Média'],['min','Mínimo'],['max','Máximo'],['count','Contar linhas'],['dcount','Contagem distinta']],'sum'),col=sel(cols,T.cols.find(c=>c.type==='num'||c.type==='int')?.name);const row=h('div',{style:{display:'grid',gridTemplateColumns:'1fr 1fr 1fr auto',gap:'6px'}},as,fn,col,h('button',{class:'tb',onclick:()=>row.remove()},'×'));aggs.append(row);col.onchange=()=>{if(as.value==='Total')as.value=col.value}};addAgg();
  dlg('Agrupar por',h('div',{},h('div',{class:'lbl2'},'Agrupar por'),ks,h('div',{class:'lbl2'},'Agregações (nome · operação · coluna)'),aggs,h('button',{class:'tb',style:{alignSelf:'flex-start'},onclick:addAgg},'+ Agregação')),[{label:'Cancelar'},{label:'OK',primary:true,act:()=>{const k=kcb.filter(x=>x[1].checked).map(x=>x[0]);const ag=[...aggs.children].map(r=>{const [a,f,c]=r.querySelectorAll('input,select');return{as:a.value||'Valor',fn:f.value,col:c.value}});if(!k.length){toast('Escolha ao menos uma coluna de agrupamento','err');return false}step({op:'groupby',keys:k,aggs:ag})}}])}
function pqMergeDlg(q,T,step){const others=BI.queries.filter(x=>x!==q);if(!others.length)return toast('Adicione outra consulta para mesclar','err');const w=sel(others.map(x=>[x.name,x.name])),k=sel(T.cols.map(c=>c.name)),k2=sel([]),kind=sel([['left','Externa esquerda (todas desta)'],['inner','Interna (somente correspondentes)']],'left');const cols=h('div',{class:'list',style:{maxHeight:'150px'}});
  const fill=()=>{const o=others.find(x=>x.name===w.value);const O=o&&(o.out||runQuery(o,new Map(BI.queries.map(x=>[x.name.toLowerCase(),x]))));k2.innerHTML='';cols.innerHTML='';(O?.cols||[]).forEach(c=>{k2.append(h('option',{value:c.name,selected:c.name.toLowerCase()===k.value.toLowerCase()||null},c.name));cols.append(h('label',{class:'li'},h('input',{type:'checkbox',checked:true,value:c.name}),c.name))})};w.onchange=fill;k.onchange=fill;fill();
  dlg('Mesclar consultas',h('div',{},h('div',{class:'row2'},field('Coluna desta consulta',k),field('Consulta',w)),h('div',{class:'row2'},field('Coluna correspondente',k2),field('Tipo de junção',kind)),h('div',{class:'lbl2'},'Colunas a trazer'),cols),[{label:'Cancelar'},{label:'OK',primary:true,act:()=>step({op:'merge',with:w.value,key:k.value,key2:k2.value,kind:kind.value,cols:[...cols.querySelectorAll('input:checked')].map(x=>x.value).filter(x=>x!==k2.value)})}])}

/* ---- relatório automático, planilha ↔ BI ---- */
function dlgAutoReport(){const tabs=[...MDL().tables.values()];if(!tabs.length)return toast('Traga dados antes (Obter dados)','err');const facts=tabs.filter(T=>BI.rels.some(r=>r.from.t===T.name));const t=sel(tabs.map(T=>[T.name,T.name]),(facts[0]||tabs.sort((a,b)=>b.rows.length-a.rows.length)[0]).name);
  dlg('Relatório automático',h('div',{},field('Tabela principal (fatos)',t),h('div',{class:'small'},'Cria uma página nova com cartões, tendência no tempo, rankings, participação, tabela e segmentações, a partir dos tipos das colunas e dos relacionamentos.')),[{label:'Cancelar'},{label:'Gerar',primary:true,act:()=>autoReport(t.value)}])}
function autoReport(tn,pageName){const T=TB(tn);if(!T)return;const p={id:uid('pg'),name:pageName||'Resumo · '+T.name,visuals:[],filters:[]};BI.pages.push(p);BI.page=BI.pages.length-1;
  const nums=T.cols.filter(c=>(c.type==='num'||c.type==='int')&&!/^(id|cod|código|codigo|ano|mês|mes|op|ordem)$/i.test(c.name)&&!/^id/i.test(c.name));const dates=T.cols.filter(c=>c.type==='date');
  const dims=[];for(const c of T.cols.filter(c=>c.type==='text')){const n=new Set(T.rows.map(r=>r[colIdx(T,c.name)])).size;if(n>1&&n<=40)dims.push({t:T.name,c:c.name,n})}
  for(const r of BI.rels.filter(r=>r.from.t===T.name)){const D=TB(r.to.t);if(!D)continue;for(const c of D.cols.filter(c=>c.type==='text'&&c.name!==r.to.c)){const n=new Set(D.rows.map(x=>x[colIdx(D,c.name)])).size;if(n>1&&n<=30)dims.push({t:D.name,c:c.name,n})}}
  dims.sort((a,b)=>a.n-b.n);const V=(type,x,y,w,hh,f,o={})=>{const v={id:uid('v'),type,x,y,w,h:hh,title:o.title||'',fields:f,opts:{legend:true,...o.opts},drill:{lvl:0,path:[]},filters:[]};if(o.slicer)v.slicer=o.slicer;p.visuals.push(v);return v};
  const meas=nums.slice(0,4).map(c=>({t:T.name,c:c.name,agg:'sum'}));const cw=meas.length?Math.floor((1280-16-16*(meas.length+1))/(meas.length+1)):0;
  V('text',16,16,meas.length?cw:400,112,{},{opts:{showTitle:false}}).text=`# ${T.name}\n${T.rows.length.toLocaleString('pt-BR')} registros${dates[0]?'\n'+fmtValue(Math.min(...T.rows.map(r=>r[colIdx(T,dates[0].name)]).filter(x=>x!=null)),'dd/mm/yyyy')+' a '+fmtValue(Math.max(...T.rows.map(r=>r[colIdx(T,dates[0].name)]).filter(x=>x!=null)),'dd/mm/yyyy'):''}`;
  meas.forEach((m,i)=>V('card',16+(i+1)*(cw+16),16,cw,112,{values:[m]}));
  const y2=144;if(dates[0]&&meas[0])V('line',16,y2,768,272,{axis:[{t:T.name,c:dates[0].name,lvl:'ym'}],values:meas.slice(0,2)},{opts:{}});
  else if(dims[2]&&meas[0])V('col',16,y2,768,272,{axis:[dims[2]],values:[meas[0]]});
  if(dims[0])V('slicer',800,y2,224,272,{axis:[dims[0]]});if(dates[0])V('slicer',1040,y2,224,272,{axis:[{t:T.name,c:dates[0].name}]},{slicer:{mode:'range'}});else if(dims[1])V('slicer',1040,y2,224,272,{axis:[dims[1]]});
  const y3=432;if(dims[1]&&meas[0])V('bar',16,y3,400,272,{axis:[dims[dims.length>2?2:1]],values:[meas[0]]});if(dims[0]&&meas[1||0])V('donut',432,y3,352,272,{axis:[dims[0]],values:[meas[1]||meas[0]]});
  const tcols=[dims[dims.length-1]||dims[0],...meas.slice(0,3)].filter(Boolean);if(tcols.length)V('table',800,y3,464,272,{cols:tcols.map((x,i)=>i?{...x,cf:i===1?'bar':undefined}:{t:x.t,c:x.c})});
  biChanged();setBIView('report');toast('Página de resumo criada')}
function regionQuery(){const sh=curSheet();const t=tableAt(sh,UI.act.r,UI.act.c);if(t){let q=BI.queries.find(q=>q.source.kind==='table'&&q.source.table===t.name);if(!q)q=addQuery({kind:'table',table:t.name},t.name,true);return q}
  const s=UI.sel;let g=s.r1!==s.r2||s.c1!==s.c2?{...s}:currentRegion(sh,UI.act.r,UI.act.c);if(g.r2>=G.nR-1)g.r2=sh.maxR;if(g.c2>=G.nC-1)g.c2=sh.maxC;if(g.r2<=g.r1)return null;
  const ref=rangeA1(g);let q=BI.queries.find(q=>q.source.kind==='range'&&q.source.sheetId===sh.id&&q.source.ref===ref);if(!q)q=addQuery({kind:'range',sheetId:sh.id,sheet:sh.name,ref,header:guessHeader(sh,g),auto:s.r1===s.r2},sh.name,true);return q}
function sendToBI(){if(UI.ed)commitEdit();const q=regionQuery();if(!q)return toast('Selecione uma tabela ou um bloco de dados com cabeçalho','err');BI_DIRTY=true;autoRelationships();setMode('bi');autoReport(q.name,'Análise · '+q.name)}
function quickChart(){if(UI.ed)commitEdit();const q=regionQuery();if(!q)return toast('Selecione dados com cabeçalho','err');BI_DIRTY=true;MDL();const T=TB(q.name);if(!T){setMode('bi');return}const txtc=T.cols.find(c=>c.type==='text')||T.cols.find(c=>c.type==='date')||T.cols[0];const nums=T.cols.filter(c=>(c.type==='num'||c.type==='int')&&c!==txtc).slice(0,3);
  setMode('bi');const v=newVisual(txtc.type==='date'?'line':'col');v.w=640;v.h=360;v.fields.axis=[{t:T.name,c:txtc.name}];v.fields.values=nums.map(c=>({t:T.name,c:c.name,agg:'sum'}));curPage().visuals.push(v);BIUI.sel=v.id;BI.view='report';biChanged();toast('Gráfico criado; use o painel Visualizações para trocar o tipo')}
function exportVisualCSV(v){const d=visualData(v);const rows=[d.head,...d.rows.map(r=>r.map((x,i)=>x==null?'':typeof x==='number'?fmtValue(x,d.fmts[i]&&!/R\$|%/.test(d.fmts[i])?'0.##########':'0.##########'):txt(x)))].map(r=>r.map(x=>/[;"\n]/.test(x)?'"'+String(x).replace(/"/g,'""')+'"':x).join(';'));downloadFile(safeName(v.title||autoTitle(v))+'.csv','\ufeff'+rows.join('\r\n'),'text/csv')}
function visualToSheet(v){const d=visualData(v);const name=uniqueSheetName((v.title||autoTitle(v)).slice(0,24)||'Dados');setMode('sheet');const ns=addSheet(name);beginTx('Dados do visual');d.head.forEach((x,j)=>{setRaw(ns,0,j,"'"+x);setStyle(ns,0,j,{b:true})});d.rows.forEach((r,i)=>r.forEach((x,j)=>{setRaw(ns,i+1,j,x==null?'':typeof x==='number'?x:"'"+txt(x));if(typeof x==='number'&&d.fmts[j])setStyle(ns,i+1,j,{nf:d.fmts[j]})}));commitTx();
  ns.tables.push({name:'Visual_'+(findTable('Visual_1')?Date.now()%10000:1),r1:0,c1:0,r2:d.rows.length,c2:d.head.length-1,style:'grafite',banded:true});autoFitCols(range(0,d.head.length-1));onChange();toast('Dados do visual copiados para a planilha '+name)}

function renderMobileReport(V){V.innerHTML='';const W=V.clientWidth-20;const wrap=h('div',{style:{padding:'10px',display:'flex',flexWrap:'wrap',gap:'10px',alignContent:'flex-start'}});V.append(wrap);BIUI.scale=1;
  const vs=[...curPage().visuals].sort((a,b)=>Math.abs(a.y-b.y)<24?a.x-b.x:a.y-b.y);
  for(const v of vs){const small=['card','kpi','gauge'].includes(v.type);const w=small?(W-10)/2:W;const hh=v.type==='card'?110:v.type==='text'?Math.min(140,v.h):small?170:v.type==='slicer'?200:v.type==='table'||v.type==='matrix'?320:260;
    const el=mkVisualEl(v,1);el.style.position='relative';el.style.left=el.style.top='auto';el.style.width=w+'px';el.style.height=hh+'px';el.querySelector('.vrs').remove();el.querySelector('.vhead').style.cursor='default';el.querySelector('.vhead').replaceWith(el.querySelector('.vhead').cloneNode(true));
    const acts=el.querySelector('.va');acts.innerHTML='';const b=h('button',{title:'Mais opções','aria-label':'Mais opções',html:ico('dots'),onclick:e=>visMenuMore(v,e)});acts.append(b);acts.classList.add('on');wrap.append(el)}
  MEMO=new Map();for(const v of curPage().visuals)biRenderVisual(v,$('#vis_'+v.id))}
